"use client";

import { useState } from "react";
import { motion } from "motion/react";

const items = ["Home", "Inbox", "Analytics", "Projects", "Team", "Settings"];

export function SidebarNavTailwind() {
  const [active, setActive] = useState("Inbox");
  const [collapsed, setCollapsed] = useState(false);
  return (
    <motion.nav
      animate={{ width: collapsed ? 64 : 240 }}
      className="flex h-96 flex-col gap-2 overflow-hidden rounded-2xl border border-zinc-800 bg-zinc-950 p-2.5 text-sm text-zinc-100"
    >
      <button onClick={() => setCollapsed(!collapsed)} aria-expanded={!collapsed} className="mb-2 self-end rounded-md px-2 py-1 text-zinc-400 hover:bg-zinc-900">
        {collapsed ? "»" : "«"}
      </button>
      {items.map((item) => (
        <button
          key={item}
          onClick={() => setActive(item)}
          aria-current={active === item ? "page" : undefined}
          className="relative flex h-9 items-center rounded-lg px-3 text-left text-zinc-400 aria-[current=page]:text-white"
        >
          {active === item && <motion.span layoutId="pill" className="absolute inset-0 rounded-lg bg-indigo-500/15 ring-1 ring-indigo-500/40" />}
          <span className="relative truncate">{collapsed ? item[0] : item}</span>
        </button>
      ))}
    </motion.nav>
  );
}
